/**
 * @file velaguard_common.h
 * @brief Common definitions for VelaGuard: event protocol, enums, data
 *        structures shared across all modules.
 *
 * Reference: PRD-05 结构化事件协议
 */

#ifndef __APP_VELAGUARD_DEVICE_VELAGUARD_COMMON_H
#define __APP_VELAGUARD_DEVICE_VELAGUARD_COMMON_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <stdint.h>
#include <stdbool.h>
#include <time.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/** Maximum number of events in circular log */
#define VG_EVENT_LOG_MAX            100

/** Maximum length of event ID string (including NUL) */
#define VG_EVENT_ID_LEN             16

/** Maximum length of device ID string (including NUL) */
#define VG_DEVICE_ID_LEN            32

/** Maximum length of summary string (including NUL) */
#define VG_SUMMARY_LEN              256

/** Maximum length of matched phrase (including NUL) */
#define VG_MATCHED_PHRASE_LEN       64

/** Maximum length of person label (including NUL) */
#define VG_PERSON_LABEL_LEN         32

/** Maximum length of ISO 8601 timestamp (including NUL) */
#define VG_TIMESTAMP_LEN            32

/** Default device ID */
#define VG_DEFAULT_DEVICE_ID        "velaguard_demo_001"

/** Configuration file path on /data partition */
#define VG_CONFIG_PATH              "/data/velaguard/config.json"

/** Event log file path on /data partition */
#define VG_EVENT_LOG_PATH           "/data/velaguard/events.json"

/** Enrollment data path on /data partition */
#define VG_ENROLLMENT_PATH          "/data/velaguard/enrollment/"

/****************************************************************************
 * Event Type Enumeration
 ****************************************************************************/

/**
 * @brief Five core sound event types plus unknown.
 * Reference: PRD-05 eventType enumeration.
 */

typedef enum
{
  VG_EVENT_ALARM_BEEP = 0,     /**< Smoke/gas alarm beep */
  VG_EVENT_DISTRESS_VOICE,     /**< Moan, cry, pain vocalization */
  VG_EVENT_WATER_FLOW,         /**< Continuous water flow / leak */
  VG_EVENT_NAME_CALL_HELP,     /**< Name call, kinship term, dialect help */
  VG_EVENT_IMPACT,             /**< Glass break, heavy impact */
  VG_EVENT_TYPE_COUNT          /**< Sentinel: number of event types */
} vg_event_type_e;

/****************************************************************************
 * Alert Level Enumeration
 ****************************************************************************/

/**
 * @brief Three-level alert hierarchy.
 * Reference: PRD-03 告警三级
 */

typedef enum
{
  VG_LEVEL_NOTICE = 0,         /**< Display status, light prompt, no remote */
  VG_LEVEL_WARNING,            /**< Local confirmation required, countdown */
  VG_LEVEL_EMERGENCY,          /**< Persistent local alert + remote notify */
  VG_LEVEL_COUNT               /**< Sentinel */
} vg_alert_level_e;

/****************************************************************************
 * Local Status Enumeration
 ****************************************************************************/

/**
 * @brief Event local processing status.
 * Reference: PRD-05 localStatus enumeration.
 */

typedef enum
{
  VG_STATUS_PENDING = 0,       /**< Awaiting user action */
  VG_STATUS_HANDLED,           /**< User confirmed as handled */
  VG_STATUS_FALSE_ALARM,       /**< User marked as false alarm */
  VG_STATUS_SNOOZED,           /**< User chose "remind later" */
  VG_STATUS_NO_RESPONSE,       /**< Countdown expired, no user action */
  VG_STATUS_COUNT              /**< Sentinel */
} vg_local_status_e;

/****************************************************************************
 * Upload Reason Enumeration
 ****************************************************************************/

typedef enum
{
  VG_UPLOAD_MANUAL_TEST = 0,   /**< Manual test injection */
  VG_UPLOAD_ESCALATED,         /**< Auto-escalated after timeout */
  VG_UPLOAD_SYNC               /**< Routine sync */
} vg_upload_reason_e;

/****************************************************************************
 * Data Structures
 ****************************************************************************/

/**
 * @brief Sound observation from audio detector.
 * Reference: PRD-01 SoundObservation.
 */

typedef struct
{
  vg_event_type_e type;        /**< Detected sound category */
  float confidence;            /**< Detection confidence [0.0, 1.0] */
  uint32_t window_ms;          /**< Analysis window length in ms */
  struct timespec timestamp;   /**< Observation timestamp */
} vg_sound_observation_t;

/**
 * @brief Distress observation from keyword/personal template matching.
 * Reference: PRD-01 DistressObservation.
 */

typedef struct
{
  vg_event_type_e type;        /**< VG_EVENT_DISTRESS_VOICE or
                                    VG_EVENT_NAME_CALL_HELP */
  char matched_phrase[VG_MATCHED_PHRASE_LEN]; /**< Matched keyword/phrase */
  char person_label[VG_PERSON_LABEL_LEN];     /**< Person identifier */
  float confidence;            /**< Match confidence [0.0, 1.0] */
  uint8_t urgency;             /**< Urgency level (0=calm, 1=moderate,
                                    2=urgent) */
  uint8_t repeat_count;        /**< Repeated utterances in window */
  struct timespec timestamp;   /**< Observation timestamp */
} vg_distress_observation_t;

/**
 * @brief Safety event: the unified event record.
 * Reference: PRD-05 SafetyEvent.
 */

typedef struct
{
  char event_id[VG_EVENT_ID_LEN];     /**< Unique event identifier */
  char device_id[VG_DEVICE_ID_LEN];   /**< Device identifier */
  vg_event_type_e event_type;         /**< Event category */
  vg_alert_level_e level;             /**< Current alert level */
  float confidence;                   /**< Combined confidence */
  char started_at[VG_TIMESTAMP_LEN];  /**< ISO 8601 start time */
  uint32_t duration_sec;              /**< Duration in seconds */
  vg_local_status_e local_status;     /**< Local processing status */
  vg_upload_reason_e upload_reason;   /**< Reason for upload */
  bool time_reliable;                 /**< Whether system time is NTP-synced */

  /* Human voice event extensions (only valid for distress/name_call) */

  char matched_phrase[VG_MATCHED_PHRASE_LEN];
  char person_label[VG_PERSON_LABEL_LEN];
  uint8_t urgency;
  uint8_t repeat_count;

  char summary[VG_SUMMARY_LEN];       /**< Human-readable summary */
} vg_safety_event_t;

/****************************************************************************
 * Helper Macros
 ****************************************************************************/

/** Convert event type to string literal */
#define VG_EVENT_TYPE_STR(t) \
  ((t) == VG_EVENT_ALARM_BEEP     ? "alarm_beep" : \
   (t) == VG_EVENT_DISTRESS_VOICE ? "distress_voice" : \
   (t) == VG_EVENT_WATER_FLOW     ? "water_flow" : \
   (t) == VG_EVENT_NAME_CALL_HELP ? "name_call_help" : \
   (t) == VG_EVENT_IMPACT         ? "impact" : "unknown")

/** Convert alert level to string literal */
#define VG_LEVEL_STR(l) \
  ((l) == VG_LEVEL_NOTICE    ? "notice" : \
   (l) == VG_LEVEL_WARNING   ? "warning" : \
   (l) == VG_LEVEL_EMERGENCY ? "emergency" : "unknown")

/** Convert local status to string literal */
#define VG_STATUS_STR(s) \
  ((s) == VG_STATUS_PENDING      ? "pending" : \
   (s) == VG_STATUS_HANDLED      ? "handled" : \
   (s) == VG_STATUS_FALSE_ALARM  ? "false_alarm" : \
   (s) == VG_STATUS_SNOOZED      ? "snoozed" : \
   (s) == VG_STATUS_NO_RESPONSE  ? "no_response" : "unknown")

/** Convert upload reason to string literal */
#define VG_UPLOAD_REASON_STR(r) \
  ((r) == VG_UPLOAD_MANUAL_TEST ? "manual_test" : \
   (r) == VG_UPLOAD_ESCALATED   ? "escalated" : \
   (r) == VG_UPLOAD_SYNC        ? "sync" : "unknown")

#endif /* __APP_VELAGUARD_DEVICE_VELAGUARD_COMMON_H */

