 ****************************************************************************/

/**
 * @file event_state_machine.c
 * @brief Event state machine implementation.
 * Reference: PRD-03 事件状态机与告警规则
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "event_state_machine.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <nuttx/clock.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_event_state_t g_active_events[VG_MAX_ACTIVE_EVENTS];
static vg_safety_event_t g_event_history[VG_EVENT_LOG_MAX];
static int g_history_head = 0;
static int g_history_count = 0;
static uint32_t g_event_counter = 0;

static vg_event_notify_cb_t g_notify_cb;
static vg_time_reliable_cb_t g_time_cb;

/* Thresholds (seconds) - demo shortened values */

/** alarm_beep: high confidence continuous -> emergency */
static const uint32_t g_alarm_emergency_sec = 5;

/** water_flow: continuous -> notice -> warning -> emergency */
static const uint32_t g_water_notice_sec = 30;
static const uint32_t g_water_warning_sec = 120;
static const uint32_t g_water_emergency_after_warning_sec = 60;

/** impact: single high-confidence -> warning; night or repeat -> emergency */
static const uint32_t g_impact_repeat_window_sec = 60;
static const uint32_t g_impact_repeat_count = 2;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Generate a unique event ID.
 */

static void generate_event_id(char *buf, size_t len)
{
  g_event_counter++;
  snprintf(buf, len, "evt_%03u", g_event_counter);
}

/**
 * @brief Get current monotonic time in seconds.
 */

static uint32_t get_monotonic_sec(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)ts.tv_sec;
}

/**
 * @brief Format current wall-clock time as ISO 8601.
 */

static void format_timestamp(char *buf, size_t len)
{
  struct timespec ts;
  struct tm tm;

  clock_gettime(CLOCK_REALTIME, &ts);
  localtime_r(&ts.tv_sec, &tm);
  strftime(buf, len, "%Y-%m-%dT%H:%M:%S+08:00", &tm);
}

/**
 * @brief Add event to circular history buffer.
 */

static void add_to_history(const vg_safety_event_t *event)
{
  memcpy(&g_event_history[g_history_head], event,
         sizeof(vg_safety_event_t));
  g_history_head = (g_history_head + 1) % VG_EVENT_LOG_MAX;
  if (g_history_count < VG_EVENT_LOG_MAX)
    {
      g_history_count++;
    }
}

/**
 * @brief Find an active event slot by event ID.
 * @return Index in g_active_events, or -1 if not found.
 */

static int find_active_event(const char *event_id)
{
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (g_active_events[i].is_active &&
          strcmp(g_active_events[i].event.event_id, event_id) == 0)
        {
          return i;
        }
    }

  return -1;
}

/**
 * @brief Find an active event slot by event type (for merging continuous
 *        detections of the same type).
 * @return Index in g_active_events, or -1 if not found.
 */

static int find_active_by_type(vg_event_type_e type)
{
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (g_active_events[i].is_active &&
          g_active_events[i].event.event_type == type &&
          g_active_events[i].event.local_status == VG_STATUS_PENDING)
        {
          return i;
        }
    }

  return -1;
}

/**
 * @brief Allocate a free active event slot.
 * @return Index or -1 if all slots full.
 */

static int alloc_active_slot(void)
{
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (!g_active_events[i].is_active)
        {
          memset(&g_active_events[i], 0, sizeof(vg_event_state_t));
          g_active_events[i].is_active = true;
          return i;
        }
    }

  return -1;
}

/**
 * @brief Close an active event (move to history, mark inactive).
 */

static void close_event(int idx, vg_local_status_e status)
{
  if (idx < 0 || idx >= VG_MAX_ACTIVE_EVENTS)
    {
      return;
    }

  g_active_events[idx].event.local_status = status;
  g_active_events[idx].event.duration_sec =
    get_monotonic_sec() - g_active_events[idx].first_seen_sec;
  add_to_history(&g_active_events[idx].event);
  g_active_events[idx].is_active = false;
}

/**
 * @brief Update event level and notify.
 */

static void set_event_level(int idx, vg_alert_level_e new_level)
{
  if (idx < 0 || idx >= VG_MAX_ACTIVE_EVENTS)
    {
      return;
    }

  if (g_active_events[idx].event.level != new_level)
    {
      g_active_events[idx].event.level = new_level;

      /* Generate summary based on level */

      const char *type_str =
        VG_EVENT_TYPE_STR(g_active_events[idx].event.event_type);
      const char *level_str = VG_LEVEL_STR(new_level);
      bool night = vg_state_machine_is_night();

      snprintf(g_active_events[idx].event.summary,
               VG_SUMMARY_LEN,
               "%s检测到%s事件，等级：%s%s",
               night ? "夜间" : "",
               type_str, level_str,
               new_level == VG_LEVEL_EMERGENCY ?
                 "，需要远程通知" : "");

      if (g_notify_cb)
        {
          g_notify_cb(&g_active_events[idx].event);
        }

      /* Update history entry */

      add_to_history(&g_active_events[idx].event);
    }
}

/**
 * @brief Priority comparison for display ordering.
 *        Higher return = higher priority.
 *        Priority: level first, then category (human > environment).
 */

static int event_priority(const vg_safety_event_t *ev)
{
  int p = ev->level * 100;  /* Level dominates */

  /* Category bonus: human safety > environment */

  switch (ev->event_type)
    {
      case VG_EVENT_DISTRESS_VOICE:
        p += 50;
        break;
      case VG_EVENT_NAME_CALL_HELP:
        p += 40;
        break;
      case VG_EVENT_ALARM_BEEP:
        p += 30;
        break;
      case VG_EVENT_IMPACT:
        p += 20;
        break;
      case VG_EVENT_WATER_FLOW:
        p += 10;
        break;
      default:
        break;
    }

  return p;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_state_machine_init(vg_event_notify_cb_t notify_cb,
                          vg_time_reliable_cb_t time_cb)
{
  memset(g_active_events, 0, sizeof(g_active_events));
  memset(g_event_history, 0, sizeof(g_event_history));
  g_history_head = 0;
  g_history_count = 0;
  g_event_counter = 0;
  g_notify_cb = notify_cb;
  g_time_cb = time_cb;

  return 0;
}

void vg_state_machine_feed_sound(const vg_sound_observation_t *obs)
{
  int idx;
  uint32_t now = get_monotonic_sec();

  if (!obs)
    {
      return;
    }

  /* Try to find existing active event of this type */

  idx = find_active_by_type(obs->type);
  if (idx < 0)
    {
      /* Create new event */

      idx = alloc_active_slot();
      if (idx < 0)
        {
          return;  /* Slots full */
        }

      generate_event_id(g_active_events[idx].event.event_id,
                        VG_EVENT_ID_LEN);
      strlcpy(g_active_events[idx].event.device_id,
              VG_DEFAULT_DEVICE_ID, VG_DEVICE_ID_LEN);
      g_active_events[idx].event.event_type = obs->type;
      g_active_events[idx].event.level = VG_LEVEL_NOTICE;
      g_active_events[idx].event.confidence = obs->confidence;
      g_active_events[idx].event.local_status = VG_STATUS_PENDING;
      g_active_events[idx].event.upload_reason = VG_UPLOAD_ESCALATED;
      g_active_events[idx].event.time_reliable = true;
      if (g_time_cb)
        {
          g_active_events[idx].event.time_reliable = g_time_cb();
        }

      format_timestamp(g_active_events[idx].event.started_at,
                       VG_TIMESTAMP_LEN);
      g_active_events[idx].first_seen_sec = now;
      g_active_events[idx].last_seen_sec = now;
      g_active_events[idx].continuous_sec = 1;
      g_active_events[idx].repeat_count = 1;
    }
  else
    {
      /* Update existing event */

      g_active_events[idx].last_seen_sec = now;
      g_active_events[idx].continuous_sec =
        now - g_active_events[idx].first_seen_sec;

      /* Check if detection is still continuous (within 2s gap) */

      if (now - g_active_events[idx].last_seen_sec > 2)
        {
          g_active_events[idx].continuous_sec = 1;
          g_active_events[idx].first_seen_sec = now;
        }

      g_active_events[idx].repeat_count++;
      if (obs->confidence > g_active_events[idx].event.confidence)
        {
          g_active_events[idx].event.confidence = obs->confidence;
        }
    }

  /* Apply event-specific rules */

  switch (obs->type)
    {
      case VG_EVENT_ALARM_BEEP:
        {
          /* High confidence continuous ~5s -> emergency directly */

          if (g_active_events[idx].event.confidence >= 0.7f &&
              g_active_events[idx].continuous_sec >= g_alarm_emergency_sec)
            {
              set_event_level(idx, VG_LEVEL_EMERGENCY);
            }
          break;
        }

      case VG_EVENT_WATER_FLOW:
        {
          uint32_t dur = g_active_events[idx].continuous_sec;

          if (dur >= g_water_warning_sec +
              g_water_emergency_after_warning_sec &&
              g_active_events[idx].event.level == VG_LEVEL_WARNING)
            {
              /* Warning exceeded, upgrade to emergency */

              set_event_level(idx, VG_LEVEL_EMERGENCY);
              g_active_events[idx].event.local_status =
                VG_STATUS_NO_RESPONSE;
            }
          else if (dur >= g_water_warning_sec)
            {
              set_event_level(idx, VG_LEVEL_WARNING);
              if (!g_active_events[idx].countdown_started)
                {
                  g_active_events[idx].countdown_started = true;
                  g_active_events[idx].countdown_start_sec = now;
                }
            }
          else if (dur >= g_water_notice_sec)
            {
              set_event_level(idx, VG_LEVEL_NOTICE);
            }
          break;
        }

      case VG_EVENT_IMPACT:
        {
          /* Single high-confidence -> warning */

          if (g_active_events[idx].event.confidence >= 0.7f &&
              g_active_events[idx].repeat_count == 1)
            {
              set_event_level(idx, VG_LEVEL_WARNING);
              if (!g_active_events[idx].countdown_started)
                {
                  g_active_events[idx].countdown_started = true;
                  g_active_events[idx].countdown_start_sec = now;
                }
            }

          /* Night or repeated within window -> emergency */

          if (vg_state_machine_is_night() ||
              (g_active_events[idx].repeat_count >= g_impact_repeat_count &&
               g_active_events[idx].continuous_sec <=
               g_impact_repeat_window_sec))
            {
              set_event_level(idx, VG_LEVEL_EMERGENCY);
            }
          break;
        }

      default:
        break;
    }
}

void vg_state_machine_feed_distress(const vg_distress_observation_t *obs)
{
  int idx;
  uint32_t now = get_monotonic_sec();

  if (!obs)
    {
      return;
    }

  idx = find_active_by_type(obs->type);
  if (idx < 0)
    {
      idx = alloc_active_slot();
      if (idx < 0)
        {
          return;
        }

      generate_event_id(g_active_events[idx].event.event_id,
                        VG_EVENT_ID_LEN);
      strlcpy(g_active_events[idx].event.device_id,
              VG_DEFAULT_DEVICE_ID, VG_DEVICE_ID_LEN);
      g_active_events[idx].event.event_type = obs->type;
      g_active_events[idx].event.level = VG_LEVEL_NOTICE;
      g_active_events[idx].event.confidence = obs->confidence;
      g_active_events[idx].event.local_status = VG_STATUS_PENDING;
      g_active_events[idx].event.upload_reason = VG_UPLOAD_ESCALATED;
      g_active_events[idx].event.time_reliable = true;
      if (g_time_cb)
        {
          g_active_events[idx].event.time_reliable = g_time_cb();
        }

      strlcpy(g_active_events[idx].event.matched_phrase,
              obs->matched_phrase, VG_MATCHED_PHRASE_LEN);
      strlcpy(g_active_events[idx].event.person_label,
              obs->person_label, VG_PERSON_LABEL_LEN);
      g_active_events[idx].event.urgency = obs->urgency;
      g_active_events[idx].event.repeat_count = obs->repeat_count;

      format_timestamp(g_active_events[idx].event.started_at,
                       VG_TIMESTAMP_LEN);
      g_active_events[idx].first_seen_sec = now;
      g_active_events[idx].last_seen_sec = now;
      g_active_events[idx].continuous_sec = 1;
      g_active_events[idx].repeat_count = 1;
    }
  else
    {
      g_active_events[idx].last_seen_sec = now;
      g_active_events[idx].continuous_sec =
        now - g_active_events[idx].first_seen_sec;
      g_active_events[idx].repeat_count++;
      g_active_events[idx].event.repeat_count = obs->repeat_count;
      g_active_events[idx].event.urgency = obs->urgency;

      if (obs->confidence > g_active_events[idx].event.confidence)
        {
          g_active_events[idx].event.confidence = obs->confidence;
        }

      if (obs->matched_phrase[0])
        {
          strlcpy(g_active_events[idx].event.matched_phrase,
                  obs->matched_phrase, VG_MATCHED_PHRASE_LEN);
        }
    }

  /* Distress/name_call rules:
   * - First detect: ask if help needed (warning level, countdown)
   * - Repeat/urgent/no response -> escalate to emergency
   */

  if (obs->type == VG_EVENT_DISTRESS_VOICE)
    {
      /* Distress voice: warning on first, emergency on repeat */

      if (g_active_events[idx].repeat_count >= 2 ||
          obs->urgency >= 2)
        {
          set_event_level(idx, VG_LEVEL_EMERGENCY);
        }
      else if (g_active_events[idx].event.level < VG_LEVEL_WARNING)
        {
          set_event_level(idx, VG_LEVEL_WARNING);
          g_active_events[idx].countdown_started = true;
          g_active_events[idx].countdown_start_sec = now;
        }
    }
  else if (obs->type == VG_EVENT_NAME_CALL_HELP)
    {
      /* Name call: calm single -> notice (local confirm only)
       * Urgent/repeat/explicit help word -> warning+ -> emergency
       */

      if (obs->urgency >= 2 ||
          g_active_events[idx].repeat_count >= 3 ||
          strstr(obs->matched_phrase, "救命") ||
          strstr(obs->matched_phrase, "快来人"))
        {
          /* Urgent: escalate quickly */

          if (g_active_events[idx].repeat_count >= 3 ||
              obs->urgency >= 2)
            {
              set_event_level(idx, VG_LEVEL_EMERGENCY);
            }
          else
            {
              set_event_level(idx, VG_LEVEL_WARNING);
              g_active_events[idx].countdown_started = true;
              g_active_events[idx].countdown_start_sec = now;
            }
        }
      else if (g_active_events[idx].event.level < VG_LEVEL_NOTICE)
        {
          /* Calm single call: just notice, ask locally */

          set_event_level(idx, VG_LEVEL_NOTICE);
        }
    }
}

int vg_state_machine_confirm_handled(const char *event_id)
{
  int idx = find_active_event(event_id);
  if (idx < 0)
    {
      return -ENOENT;
    }

  close_event(idx, VG_STATUS_HANDLED);
  return 0;
}

int vg_state_machine_confirm_false_alarm(const char *event_id)
{
  int idx = find_active_event(event_id);
  if (idx < 0)
    {
      return -ENOENT;
    }

  close_event(idx, VG_STATUS_FALSE_ALARM);
  return 0;
}

int vg_state_machine_snooze(const char *event_id)
{
  int idx = find_active_event(event_id);
  if (idx < 0)
    {
      return -ENOENT;
    }

  if (g_active_events[idx].snooze_count >= VG_MAX_SNOOZE_COUNT)
    {
      /* Third snooze: treat as no_response and escalate */

      g_active_events[idx].event.local_status = VG_STATUS_NO_RESPONSE;
      set_event_level(idx, VG_LEVEL_EMERGENCY);
      return -EAGAIN;
    }

  g_active_events[idx].snooze_count++;
  g_active_events[idx].event.local_status = VG_STATUS_SNOOZED;
  g_active_events[idx].countdown_started = false;

  /* Record in history */

  add_to_history(&g_active_events[idx].event);
  return 0;
}

void vg_state_machine_tick(void)
{
  uint32_t now = get_monotonic_sec();
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (!g_active_events[i].is_active)
        {
          continue;
        }

      /* Handle snooze timeout */

      if (g_active_events[i].event.local_status == VG_STATUS_SNOOZED)
        {
          /* Check if snooze period elapsed */

          if (now - g_active_events[i].last_seen_sec >=
              VG_SNOOZE_DURATION_SEC)
            {
              /* Re-enter warning countdown */

              g_active_events[i].event.local_status = VG_STATUS_PENDING;
              g_active_events[i].countdown_started = true;
              g_active_events[i].countdown_start_sec = now;
              g_active_events[i].last_seen_sec = now;
              set_event_level(i, VG_LEVEL_WARNING);
            }
          continue;
        }

      /* Handle warning countdown expiry */

      if (g_active_events[i].countdown_started &&
          g_active_events[i].event.level == VG_LEVEL_WARNING)
        {
          if (now - g_active_events[i].countdown_start_sec >=
              VG_WARNING_TIMEOUT_SEC)
            {
              /* Timeout: no response -> emergency */

              g_active_events[i].event.local_status =
                VG_STATUS_NO_RESPONSE;
              set_event_level(i, VG_LEVEL_EMERGENCY);
            }
        }

      /* Age out very old events that haven't been detected recently */

      if (now - g_active_events[i].last_seen_sec > 300)
        {
          close_event(i, VG_STATUS_NO_RESPONSE);
        }
    }
}

const vg_safety_event_t *vg_state_machine_get_priority_event(void)
{
  int best_idx = -1;
  int best_priority = -1;
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (!g_active_events[i].is_active)
        {
          continue;
        }

      int p = event_priority(&g_active_events[i].event);
      if (p > best_priority)
        {
          best_priority = p;
          best_idx = i;
        }
    }

  if (best_idx >= 0)
    {
      return &g_active_events[best_idx].event;
    }

  return NULL;
}

int vg_state_machine_get_active_count(void)
{
  int count = 0;
  int i;

  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
    {
      if (g_active_events[i].is_active)
        {
          count++;
        }
    }

  return count;
}

int vg_state_machine_get_history(vg_safety_event_t *events, int max)
{
  int count = 0;
  int idx;
  int i;

  if (!events || max <= 0)
    {
      return 0;
    }

  /* Return most recent first */

  idx = (g_history_head - 1 + VG_EVENT_LOG_MAX) % VG_EVENT_LOG_MAX;
  for (i = 0; i < g_history_count && count < max; i++)
    {
      memcpy(&events[count], &g_event_history[idx],
             sizeof(vg_safety_event_t));
      count++;
      idx = (idx - 1 + VG_EVENT_LOG_MAX) % VG_EVENT_LOG_MAX;
    }

  return count;
}

void vg_state_machine_inject_event(const vg_safety_event_t *event)
{
  int idx;

  if (!event)
    {
      return;
    }

  idx = alloc_active_slot();
  if (idx < 0)
    {
      return;
    }

  memcpy(&g_active_events[idx].event, event, sizeof(vg_safety_event_t));
  g_active_events[idx].first_seen_sec = get_monotonic_sec();
  g_active_events[idx].last_seen_sec = g_active_events[idx].first_seen_sec;
  g_active_events[idx].continuous_sec = 1;
  g_active_events[idx].repeat_count = 1;

  if (g_notify_cb)
    {
      g_notify_cb(&g_active_events[idx].event);
    }

  add_to_history(&g_active_events[idx].event);
}

bool vg_state_machine_is_night(void)
{
  struct timespec ts;
  struct tm tm;
  int hour;

  /* If time is not reliable, don't apply night rules */

  if (g_time_cb && !g_time_cb())
    {
      return false;
    }

  clock_gettime(CLOCK_REALTIME, &ts);
  localtime_r(&ts.tv_sec, &tm);
  hour = tm.tm_hour;

  return (hour >= VG_NIGHT_START_HOUR || hour < VG_NIGHT_END_HOUR);
}

