/**
 * @file event_log.c
 * @brief Persistent event log implementation using /data partition.
 * Reference: PRD-05
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "event_log.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_safety_event_t g_log_buffer[VG_EVENT_LOG_MAX];
static int g_log_head = 0;
static int g_log_count = 0;
static bool g_initialized = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Ensure /data/velaguard/ directory exists.
 */

static void ensure_data_dir(void)
{
  mkdir("/data/velaguard", 0755);
}

/**
 * @brief Write the entire log buffer to disk atomically.
 */

static int persist_log(void)
{
  FILE *fp;
  int i;
  int idx;

  ensure_data_dir();

  fp = fopen(VG_EVENT_LOG_PATH, "w");
  if (!fp)
    {
      return -errno;
    }

  /* Write count header */

  fprintf(fp, "%d\n", g_log_count);

  /* Write events oldest first */

  idx = (g_log_head - g_log_count + VG_EVENT_LOG_MAX) % VG_EVENT_LOG_MAX;
  for (i = 0; i < g_log_count; i++)
    {
      char json[1024];
      int len = vg_event_to_json(&g_log_buffer[idx], json, sizeof(json));
      if (len > 0)
        {
          fprintf(fp, "%s\n", json);
        }

      idx = (idx + 1) % VG_EVENT_LOG_MAX;
    }

  fclose(fp);
  return 0;
}

/**
 * @brief Load log from disk.
 */

static int load_log(void)
{
  FILE *fp;
  char line[1024];
  int count;
  int loaded = 0;

  fp = fopen(VG_EVENT_LOG_PATH, "r");
  if (!fp)
    {
      return -errno;
    }

  if (fgets(line, sizeof(line), fp) == NULL)
    {
      fclose(fp);
      return -EIO;
    }

  count = atoi(line);
  if (count < 0 || count > VG_EVENT_LOG_MAX)
    {
      count = VG_EVENT_LOG_MAX;
    }

  while (loaded < count && fgets(line, sizeof(line), fp) != NULL)
    {
      /* Remove trailing newline */

      char *nl = strchr(line, '\n');
      if (nl)
        {
          *nl = '\0';
        }

      if (strlen(line) < 10)
        {
          continue;
        }

      vg_safety_event_t ev;
      if (vg_event_from_json(line, &ev) == 0)
        {
          int idx = (g_log_head) % VG_EVENT_LOG_MAX;
          memcpy(&g_log_buffer[idx], &ev, sizeof(vg_safety_event_t));
          g_log_head = (g_log_head + 1) % VG_EVENT_LOG_MAX;
          loaded++;
        }
    }

  g_log_count = loaded;
  fclose(fp);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_event_log_init(void)
{
  if (g_initialized)
    {
      return 0;
    }

  memset(g_log_buffer, 0, sizeof(g_log_buffer));
  g_log_head = 0;
  g_log_count = 0;

  load_log();
  g_initialized = true;
  return 0;
}

int vg_event_log_append(const vg_safety_event_t *event)
{
  int idx;

  if (!event)
    {
      return -EINVAL;
    }

  idx = g_log_head % VG_EVENT_LOG_MAX;
  memcpy(&g_log_buffer[idx], event, sizeof(vg_safety_event_t));
  g_log_head = (g_log_head + 1) % VG_EVENT_LOG_MAX;

  if (g_log_count < VG_EVENT_LOG_MAX)
    {
      g_log_count++;
    }

  return persist_log();
}

int vg_event_log_get_recent(vg_safety_event_t *events, int max)
{
  int count = 0;
  int idx;
  int i;

  if (!events || max <= 0)
    {
      return 0;
    }

  idx = (g_log_head - 1 + VG_EVENT_LOG_MAX) % VG_EVENT_LOG_MAX;
  for (i = 0; i < g_log_count && count < max; i++)
    {
      memcpy(&events[count], &g_log_buffer[idx],
             sizeof(vg_safety_event_t));
      count++;
      idx = (idx - 1 + VG_EVENT_LOG_MAX) % VG_EVENT_LOG_MAX;
    }

  return count;
}

int vg_event_log_get_count(void)
{
  return g_log_count;
}

int vg_event_log_clear(void)
{
  g_log_head = 0;
  g_log_count = 0;
  memset(g_log_buffer, 0, sizeof(g_log_buffer));
  return persist_log();
}

int vg_event_to_json(const vg_safety_event_t *event, char *buf, size_t len)
{
  int n;

  if (!event || !buf || len == 0)
    {
      return -EINVAL;
    }

  n = snprintf(buf, len,
    "{"
    "\"eventId\":\"%s\","
    "\"deviceId\":\"%s\","
    "\"eventType\":\"%s\","
    "\"level\":\"%s\","
    "\"confidence\":%.2f,"
    "\"startedAt\":\"%s\","
    "\"durationSec\":%u,"
    "\"localStatus\":\"%s\","
    "\"uploadReason\":\"%s\","
    "\"timeReliable\":%s",
    event->event_id,
    event->device_id,
    VG_EVENT_TYPE_STR(event->event_type),
    VG_LEVEL_STR(event->level),
    event->confidence,
    event->started_at,
    event->duration_sec,
    VG_STATUS_STR(event->local_status),
    VG_UPLOAD_REASON_STR(event->upload_reason),
    event->time_reliable ? "true" : "false");

  /* Add human voice fields if applicable */

  if (event->event_type == VG_EVENT_DISTRESS_VOICE ||
      event->event_type == VG_EVENT_NAME_CALL_HELP)
    {
      if (event->matched_phrase[0])
        {
          n += snprintf(buf + n, len - n,
                        ",\"matchedPhrase\":\"%s\"",
                        event->matched_phrase);
        }

      if (event->person_label[0])
        {
          n += snprintf(buf + n, len - n,
                        ",\"personLabel\":\"%s\"",
                        event->person_label);
        }

      n += snprintf(buf + n, len - n,
                    ",\"urgency\":%u,\"repeatCount\":%u",
                    event->urgency, event->repeat_count);
    }

  if (event->summary[0])
    {
      n += snprintf(buf + n, len - n,
                    ",\"summary\":\"%s\"", event->summary);
    }

  n += snprintf(buf + n, len - n, "}");
  return n;
}

int vg_event_from_json(const char *json, vg_safety_event_t *event)
{
  const char *p;

  if (!json || !event)
    {
      return -EINVAL;
    }

  memset(event, 0, sizeof(vg_safety_event_t));

  /* Simple manual JSON parsing (no cJSON dependency for NuttX) */

  /* eventId */

  p = strstr(json, "\"eventId\":\"");
  if (p)
    {
      p += 11;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_EVENT_ID_LEN)
            {
              copylen = VG_EVENT_ID_LEN - 1;
            }

          memcpy(event->event_id, p, copylen);
        }
    }

  /* deviceId */

  p = strstr(json, "\"deviceId\":\"");
  if (p)
    {
      p += 12;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_DEVICE_ID_LEN)
            {
              copylen = VG_DEVICE_ID_LEN - 1;
            }

          memcpy(event->device_id, p, copylen);
        }
    }

  /* eventType */

  p = strstr(json, "\"eventType\":\"");
  if (p)
    {
      p += 13;
      if (strncmp(p, "alarm_beep", 10) == 0)
        {
          event->event_type = VG_EVENT_ALARM_BEEP;
        }
      else if (strncmp(p, "distress_voice", 14) == 0)
        {
          event->event_type = VG_EVENT_DISTRESS_VOICE;
        }
      else if (strncmp(p, "water_flow", 10) == 0)
        {
          event->event_type = VG_EVENT_WATER_FLOW;
        }
      else if (strncmp(p, "name_call_help", 14) == 0)
        {
          event->event_type = VG_EVENT_NAME_CALL_HELP;
        }
      else if (strncmp(p, "impact", 6) == 0)
        {
          event->event_type = VG_EVENT_IMPACT;
        }
    }

  /* level */

  p = strstr(json, "\"level\":\"");
  if (p)
    {
      p += 9;
      if (strncmp(p, "notice", 6) == 0)
        {
          event->level = VG_LEVEL_NOTICE;
        }
      else if (strncmp(p, "warning", 7) == 0)
        {
          event->level = VG_LEVEL_WARNING;
        }
      else if (strncmp(p, "emergency", 9) == 0)
        {
          event->level = VG_LEVEL_EMERGENCY;
        }
    }

  /* confidence */

  p = strstr(json, "\"confidence\":");
  if (p)
    {
      event->confidence = strtof(p + 13, NULL);
    }

  /* startedAt */

  p = strstr(json, "\"startedAt\":\"");
  if (p)
    {
      p += 13;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_TIMESTAMP_LEN)
            {
              copylen = VG_TIMESTAMP_LEN - 1;
            }

          memcpy(event->started_at, p, copylen);
        }
    }

  /* durationSec */

  p = strstr(json, "\"durationSec\":");
  if (p)
    {
      event->duration_sec = strtoul(p + 14, NULL, 10);
    }

  /* localStatus */

  p = strstr(json, "\"localStatus\":\"");
  if (p)
    {
      p += 15;
      if (strncmp(p, "pending", 7) == 0)
        {
          event->local_status = VG_STATUS_PENDING;
        }
      else if (strncmp(p, "handled", 7) == 0)
        {
          event->local_status = VG_STATUS_HANDLED;
        }
      else if (strncmp(p, "false_alarm", 11) == 0)
        {
          event->local_status = VG_STATUS_FALSE_ALARM;
        }
      else if (strncmp(p, "snoozed", 7) == 0)
        {
          event->local_status = VG_STATUS_SNOOZED;
        }
      else if (strncmp(p, "no_response", 11) == 0)
        {
          event->local_status = VG_STATUS_NO_RESPONSE;
        }
    }

  /* summary */

  p = strstr(json, "\"summary\":\"");
  if (p)
    {
      p += 11;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_SUMMARY_LEN)
            {
              copylen = VG_SUMMARY_LEN - 1;
            }

          memcpy(event->summary, p, copylen);
        }
    }

  /* matchedPhrase */

  p = strstr(json, "\"matchedPhrase\":\"");
  if (p)
    {
      p += 17;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_MATCHED_PHRASE_LEN)
            {
              copylen = VG_MATCHED_PHRASE_LEN - 1;
            }

          memcpy(event->matched_phrase, p, copylen);
        }
    }

  /* personLabel */

  p = strstr(json, "\"personLabel\":\"");
  if (p)
    {
      p += 15;
      const char *end = strchr(p, '"');
      if (end)
        {
          size_t copylen = end - p;
          if (copylen >= VG_PERSON_LABEL_LEN)
            {
              copylen = VG_PERSON_LABEL_LEN - 1;
            }

          memcpy(event->person_label, p, copylen);
        }
    }

  /* urgency */

  p = strstr(json, "\"urgency\":");
  if (p)
    {
      event->urgency = strtoul(p + 10, NULL, 10);
    }

  /* repeatCount */

  p = strstr(json, "\"repeatCount\":");
  if (p)
    {
      event->repeat_count = strtoul(p + 14, NULL, 10);
    }

  /* timeReliable */

  p = strstr(json, "\"timeReliable\":");
  if (p)
    {
      p += 15;
      event->time_reliable = (strncmp(p, "true", 4) == 0);
    }

  return 0;
}

