/**
 * @file hardware_adapter.c
 * @brief Hardware adapter implementation.
 *        In simulator/development mode, outputs to serial console.
 *        On real hardware, drives LCD, WS2812 LED, and speaker.
 * Reference: PRD-04
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "hardware_adapter.h"
#include <stdio.h>
#include <string.h>
#include <nuttx/clock.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_current_page = VG_PAGE_MONITOR;
static vg_button_cb_t g_button_cb;
static bool g_guarding_paused = false;
static char g_paused_reason[64] = "";

/* Simulated hardware state for simulator mode */

static uint32_t g_led_color = VG_LED_OFF;
static int g_led_pattern = 0;
static bool g_wifi_connected = false;
static bool g_time_synced = false;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_hw_init(void)
{
  g_current_page = VG_PAGE_MONITOR;
  g_led_color = VG_LED_GREEN;
  g_led_pattern = 4; /* Breathing = guarding */

  printf("[HW] Hardware adapter initialized (simulator mode)\n");
  printf("[HW] LCD: 3-page UI ready\n");
  printf("[HW] LED: WS2812 simulated\n");
  printf("[HW] Speaker: tone simulation via serial\n");
  printf("[HW] Buttons: serial command input\n");

  return 0;
}

void vg_hw_set_page(int page)
{
  if (page >= VG_PAGE_MONITOR && page <= VG_PAGE_HISTORY)
    {
      g_current_page = page;
    }
}

int vg_hw_get_page(void)
{
  return g_current_page;
}

void vg_hw_update_monitor_page(bool guarding, bool wifi_ok,
                                bool time_synced,
                                const vg_safety_event_t *event)
{
  g_wifi_connected = wifi_ok;
  g_time_synced = time_synced;

  printf("\n=== VelaGuard Monitor Page ===\n");
  printf("Guard: %s%s\n",
         guarding ? "ACTIVE" : "PAUSED",
         g_guarding_paused ? g_paused_reason : "");
  printf("WiFi: %s | Time: %s\n",
         wifi_ok ? "Connected" : "Disconnected",
         time_synced ? "Synced" : "Not synced");

  if (event)
    {
      printf("Last event: %s [%s] conf=%.2f\n",
             VG_EVENT_TYPE_STR(event->event_type),
             VG_LEVEL_STR(event->level),
             event->confidence);
    }
  else
    {
      printf("No recent events\n");
    }

  printf("[BTN4] Enrollment | [BTN_OK] Confirm\n");
  printf("==============================\n");
}

void vg_hw_update_confirm_page(const vg_safety_event_t *event,
                                uint32_t countdown)
{
  if (!event)
    {
      return;
    }

  printf("\n=== Event Confirmation ===\n");
  printf("Type:  %s\n", VG_EVENT_TYPE_STR(event->event_type));
  printf("Level: %s\n", VG_LEVEL_STR(event->level));
  printf("Conf:  %.2f\n", event->confidence);
  printf("Time:  %s\n", event->started_at);

  if (event->matched_phrase[0])
    {
      printf("Phrase: %s\n", event->matched_phrase);
    }

  if (event->person_label[0])
    {
      printf("Person: %s\n", event->person_label);
    }

  if (countdown > 0)
    {
      printf("Countdown: %u seconds\n", countdown);
    }

  printf("\n[BTN_OK] Handled | [BTN_BACK] False Alarm | [BTN_DOWN] Snooze\n");
  printf("==============================\n");
}

void vg_hw_update_history_page(const vg_safety_event_t *events,
                                int count, int scroll_offset)
{
  int i;

  printf("\n=== Event History ===\n");
  if (count == 0)
    {
      printf("No events recorded.\n");
