  else
    {
      for (i = scroll_offset; i < count && i < scroll_offset + 5; i++)
        {
          printf("[%s] %s %s conf=%.2f %s\n",
                 events[i].event_id,
                 VG_EVENT_TYPE_STR(events[i].event_type),
                 VG_LEVEL_STR(events[i].level),
                 events[i].confidence,
                 VG_STATUS_STR(events[i].local_status));
