  else if (color == VG_LED_YELLOW)
    {
      color_name = "YELLOW";
    }
  else if (color == VG_LED_RED)
    {
      color_name = "RED";
    }

  switch (pattern)
    {
      case 1:
        pattern_name = "steady";
        break;
      case 2:
        pattern_name = "slow-blink";
        break;
      case 3:
        pattern_name = "fast-blink";
        break;
      case 4:
        pattern_name = "breathing";
        break;
      default:
        pattern_name = "off";
        break;
    }

  printf("[LED] %s %s\n", color_name, pattern_name);
