/**
 * @file audio_detector.c
 * @brief Audio detector implementation.
 *        In simulator mode, provides simulation functions.
 *        On real hardware, captures from microphone and runs inference.
 * Reference: PRD-01
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "audio_detector.h"
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <unistd.h>
#include <nuttx/clock.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_audio_sound_cb_t g_sound_cb;
static vg_audio_distress_cb_t g_distress_cb;
static bool g_active = false;
static pthread_t g_capture_thread;

/* Performance statistics */

static float g_avg_inference_ms = 0.0f;
static float g_max_inference_ms = 0.0f;
static uint32_t g_total_frames = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Audio capture and analysis thread (real hardware path).
 *        In simulator mode, this is a placeholder.
 */

static void *capture_thread(void *arg)
{
  printf("[AUDIO] Capture thread started\n");

  while (g_active)
    {
      /* In simulator mode, just sleep and wait for injected events */

      usleep(100000); /* 100ms */

      /* On real hardware, this would:
       * 1. Read from media server (48kHz)
       * 2. Resample to 16kHz mono
       * 3. Apply sliding window (1s, 50% overlap)
       * 4. Extract MFCC/log-mel features
       * 5. Run environment sound classifier (DS-CNN)
       * 6. Run distress voice detector
       * 7. Run keyword/template matcher
       * 8. Fire callbacks for detections above threshold
       */
    }

  printf("[AUDIO] Capture thread stopped\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_audio_init(vg_audio_sound_cb_t sound_cb,
                  vg_audio_distress_cb_t distress_cb)
{
  if (!sound_cb || !distress_cb)
    {
      return -EINVAL;
    }

  g_sound_cb = sound_cb;
  g_distress_cb = distress_cb;
  g_active = false;
  g_total_frames = 0;
  g_avg_inference_ms = 0.0f;
  g_max_inference_ms = 0.0f;

  printf("[AUDIO] Audio detector initialized\n");
  return 0;
}

int vg_audio_start(void)
{
  int ret;

  if (g_active)
    {
      return -EALREADY;
    }

  g_active = true;

  ret = pthread_create(&g_capture_thread, NULL, capture_thread, NULL);
  if (ret != 0)
    {
      g_active = false;
      return -ret;
    }

  printf("[AUDIO] Audio monitoring started\n");
  return 0;
}

int vg_audio_stop(void)
{
  if (!g_active)
    {
      return 0;
    }

  g_active = false;
  pthread_join(g_capture_thread, NULL);

  printf("[AUDIO] Audio monitoring stopped\n");
  return 0;
}

bool vg_audio_is_active(void)
{
  return g_active;
}

void vg_audio_get_stats(float *avg_ms, float *max_ms, uint32_t *frames)
{
  if (avg_ms)
    {
      *avg_ms = g_avg_inference_ms;
    }

  if (max_ms)
    {
      *max_ms = g_max_inference_ms;
    }

  if (frames)
    {
      *frames = g_total_frames;
    }
}

void vg_audio_simulate_sound(const vg_sound_observation_t *obs)
{
  if (!obs || !g_sound_cb)
    {
      return;
    }

  printf("[AUDIO-SIM] Sound: %s conf=%.2f\n",
         VG_EVENT_TYPE_STR(obs->type), obs->confidence);

  g_sound_cb(obs);
  g_total_frames++;
}

void vg_audio_simulate_distress(const vg_distress_observation_t *obs)
{
  if (!obs || !g_distress_cb)
    {
      return;
    }

  printf("[AUDIO-SIM] Distress: %s phrase='%s' urgency=%u repeat=%u\n",
         VG_EVENT_TYPE_STR(obs->type),
         obs->matched_phrase,
         obs->urgency,
         obs->repeat_count);

  g_distress_cb(obs);
  g_total_frames++;
}

