/**
 * @file enrollment.c
 * @brief Personalized enrollment implementation.
 * Reference: PRD-02
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "enrollment.h"
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <sys/stat.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_enrollment_entry_t g_enrollments[VG_MAX_ENROLLMENTS];
static int g_enroll_count = 0;

/* Current enrollment session */

static vg_enroll_state_e g_state = VG_ENROLL_IDLE;
static int g_current_index = -1;
static int g_sample_count = 0;
static float g_sample_accum[64]; /* Accumulated features */

/* Preset labels */

static const char *g_preset_labels[] =
{
  "家庭成员A", "家庭成员B", "老伴",
  "儿子", "女儿", "孙子/孙女", "护工"
};

#define NUM_PRESET_LABELS \
  (sizeof(g_preset_labels) / sizeof(g_preset_labels[0]))

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Ensure enrollment directory exists.
 */

static void ensure_enroll_dir(void)
{
  mkdir("/data/velaguard", 0755);
  mkdir(VG_ENROLLMENT_PATH, 0755);
}

/**
 * @brief Save enrollment data to file.
 */

static int save_enrollments(void)
{
  FILE *fp;
  int i;

  ensure_enroll_dir();

  fp = fopen(VG_ENROLLMENT_PATH "enrollments.dat", "w");
  if (!fp)
    {
      return -errno;
    }

  fprintf(fp, "%d\n", g_enroll_count);

  for (i = 0; i < g_enroll_count; i++)
    {
      fprintf(fp, "%s|%s|%u|%d\n",
              g_enrollments[i].label,
              g_enrollments[i].phrase,
              g_enrollments[i].urgency_type,
              g_enrollments[i].is_active ? 1 : 0);
    }

  fclose(fp);
  return 0;
}

/**
 * @brief Load enrollment data from file.
 */

static int load_enrollments(void)
{
  FILE *fp;
  char line[256];
  int count;
  int i;

  fp = fopen(VG_ENROLLMENT_PATH "enrollments.dat", "r");
  if (!fp)
    {
      return -errno;
    }

  if (fgets(line, sizeof(line), fp) == NULL)
    {
      fclose(fp);
      return -EIO;
    }

  count = atoi(line);
  if (count < 0 || count > VG_MAX_ENROLLMENTS)
    {
      count = VG_MAX_ENROLLMENTS;
    }

  g_enroll_count = 0;
  for (i = 0; i < count; i++)
    {
      if (fgets(line, sizeof(line), fp) == NULL)
        {
          break;
        }

      char *nl = strchr(line, '\n');
      if (nl)
        {
          *nl = '\0';
        }

      /* Parse: label|phrase|urgency_type|is_active */

      char *p = line;
      char *sep;

      sep = strchr(p, '|');
      if (!sep)
        {
          continue;
        }

      *sep = '\0';
      strlcpy(g_enrollments[i].label, p, VG_PERSON_LABEL_LEN);
      p = sep + 1;

      sep = strchr(p, '|');
      if (!sep)
        {
          continue;
        }

      *sep = '\0';
      strlcpy(g_enrollments[i].phrase, p, VG_MATCHED_PHRASE_LEN);
      p = sep + 1;

      sep = strchr(p, '|');
      if (!sep)
        {
          continue;
        }

      *sep = '\0';
      g_enrollments[i].urgency_type = atoi(p);
      p = sep + 1;

      g_enrollments[i].is_active = (atoi(p) == 1);
      g_enroll_count = i + 1;
    }

  fclose(fp);
  return 0;
}

/**
 * @brief Extract simple MFCC-like features from audio.
 *        This is a simplified version for template matching.
 */

static void extract_features(const int16_t *audio, uint32_t samples,
                             float *features, int dim)
{
  uint32_t i;
  int d;
  float sum;
  float mean;

  /* Simple energy-based features per sub-band */

  int band_size = samples / dim;
  if (band_size < 1)
    {
      band_size = 1;
    }

  /* Calculate mean for DC removal */

  sum = 0.0f;
  for (i = 0; i < samples; i++)
    {
      sum += (float)audio[i];
    }

  mean = sum / samples;

  for (d = 0; d < dim; d++)
    {
      uint32_t start = d * band_size;
      uint32_t end = start + band_size;
      float energy = 0.0f;

      if (end > samples)
        {
          end = samples;
        }

      for (i = start; i < end; i++)
        {
          float sample = (float)audio[i] - mean;
          energy += sample * sample;
        }

      features[d] = sqrtf(energy / band_size) / 32768.0f;
    }
}

/**
 * @brief Calculate cosine similarity between two feature vectors.
 */

static float cosine_similarity(const float *a, const float *b, int dim)
{
  float dot = 0.0f;
  float norm_a = 0.0f;
  float norm_b = 0.0f;
  int i;

  for (i = 0; i < dim; i++)
    {
      dot += a[i] * b[i];
      norm_a += a[i] * a[i];
      norm_b += b[i] * b[i];
    }

  if (norm_a < 1e-10f || norm_b < 1e-10f)
    {
      return 0.0f;
    }

  return dot / (sqrtf(norm_a) * sqrtf(norm_b));
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_enrollment_init(void)
{
  memset(g_enrollments, 0, sizeof(g_enrollments));
  g_enroll_count = 0;
  g_state = VG_ENROLL_IDLE;
  g_current_index = -1;

  load_enrollments();

  printf("[ENROLL] Enrollment module initialized, %d templates loaded\n",
         g_enroll_count);
  return 0;
}

int vg_enrollment_start(const char *label, const char *phrase)
{
  int idx;

  if (!label || !phrase)
    {
      return -EINVAL;
    }

  if (g_state != VG_ENROLL_IDLE)
    {
      return -EBUSY;
    }

  /* Find a free slot */

  for (idx = 0; idx < VG_MAX_ENROLLMENTS; idx++)
    {
      if (!g_enrollments[idx].is_active)
        {
          break;
        }
    }

  if (idx >= VG_MAX_ENROLLMENTS)
    {
      return -ENOSPC;
    }

  memset(&g_enrollments[idx], 0, sizeof(vg_enrollment_entry_t));
  strlcpy(g_enrollments[idx].label, label, VG_PERSON_LABEL_LEN);
  strlcpy(g_enrollments[idx].phrase, phrase, VG_MATCHED_PHRASE_LEN);
  g_enrollments[idx].is_active = true;

  g_current_index = idx;
  g_sample_count = 0;
  g_state = VG_ENROLL_RECORDING;
  memset(g_sample_accum, 0, sizeof(g_sample_accum));

  printf("[ENROLL] Starting enrollment: '%s' (%s)\n", label, phrase);
  return 0;
}

int vg_enrollment_feed_sample(const int16_t *audio, uint32_t samples)
{
  float features[64];

  if (g_state != VG_ENROLL_RECORDING)
    {
      return -EPROTO;
    }

  if (!audio || samples == 0)
    {
      return -EINVAL;
    }

  /* Extract features from this sample */

  extract_features(audio, samples, features, 64);

  /* Accumulate for averaging */

  int i;
  for (i = 0; i < 64; i++)
    {
      g_sample_accum[i] += features[i];
    }

  g_sample_count++;
  printf("[ENROLL] Sample %d/%d recorded\n",
         g_sample_count, VG_ENROLL_SAMPLES);

  if (g_sample_count >= VG_ENROLL_SAMPLES)
    {
      /* Average the features to create template */

      for (i = 0; i < 64; i++)
        {
          g_enrollments[g_current_index].template_features[i] =
            g_sample_accum[i] / VG_ENROLL_SAMPLES;
        }

      g_state = VG_ENROLL_DONE;
      g_enroll_count++;
      save_enrollments();

      printf("[ENROLL] Enrollment complete: '%s'\n",
             g_enrollments[g_current_index].label);
      return 0;
    }

  return -EAGAIN; /* More samples needed */
}

vg_enroll_state_e vg_enrollment_get_state(void)
{
  return g_state;
}

int vg_enrollment_get_sample_count(void)
{
  return g_sample_count;
}

void vg_enrollment_cancel(void)
{
  if (g_current_index >= 0 &&
      g_current_index < VG_MAX_ENROLLMENTS)
    {
      g_enrollments[g_current_index].is_active = false;
    }

  g_state = VG_ENROLL_IDLE;
  g_current_index = -1;
  g_sample_count = 0;

  printf("[ENROLL] Enrollment cancelled\n");
}

int vg_enrollment_delete(int index)
{
  if (index < 0 || index >= VG_MAX_ENROLLMENTS)
    {
      return -EINVAL;
    }

  if (!g_enrollments[index].is_active)
    {
      return -ENOENT;
    }

  printf("[ENROLL] Deleting template: '%s'\n",
         g_enrollments[index].label);

  g_enrollments[index].is_active = false;
  memset(&g_enrollments[index], 0, sizeof(vg_enrollment_entry_t));
  save_enrollments();

  return 0;
}

int vg_enrollment_get_all(vg_enrollment_entry_t *entries, int max)
{
  int count = 0;
  int i;

  if (!entries || max <= 0)
    {
      return 0;
    }

  for (i = 0; i < VG_MAX_ENROLLMENTS && count < max; i++)
    {
      if (g_enrollments[i].is_active)
        {
          memcpy(&entries[count], &g_enrollments[i],
                 sizeof(vg_enrollment_entry_t));
          count++;
        }
    }

  return count;
}

int vg_enrollment_match(const int16_t *audio, uint32_t samples,
                        vg_enrollment_entry_t *best_match,
                        float *confidence)
{
  float features[64];
  float best_sim = 0.0f;
  int best_idx = -1;
  int i;

  if (!audio || samples == 0)
    {
      return -1;
    }

  extract_features(audio, samples, features, 64);

  for (i = 0; i < VG_MAX_ENROLLMENTS; i++)
    {
      if (!g_enrollments[i].is_active)
        {
          continue;
        }

      float sim = cosine_similarity(features,
                                     g_enrollments[i].template_features,
                                     64);
      if (sim > best_sim)
        {
          best_sim = sim;
          best_idx = i;
        }
    }

  if (best_idx >= 0 && best_sim >= 0.7f)
    {
      if (best_match)
        {
          memcpy(best_match, &g_enrollments[best_idx],
                 sizeof(vg_enrollment_entry_t));
        }

      if (confidence)
        {
          *confidence = best_sim;
        }

      return best_idx;
    }

  return -1;
}

int vg_enrollment_save(void)
{
  return save_enrollments();
}

int vg_enrollment_get_count(void)
{
  int count = 0;
  int i;

  for (i = 0; i < VG_MAX_ENROLLMENTS; i++)
    {
      if (g_enrollments[i].is_active)
        {
          count++;
        }
    }

  return count;
}

