/**
 * @file uploader.c
 * @brief Uploader implementation: HTTP POST to prototype console.
 * Reference: PRD-05
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include "uploader.h"
#include "../event_log/event_log.h"
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

/****************************************************************************
 * Private Data
 ****************************************************************************/

static char g_console_url[256] = VG_DEFAULT_CONSOLE_URL;
static char g_console_host[128] = "192.168.1.100";
static int g_console_port = 3000;
static bool g_console_reachable = false;

/* Retry queue */

static vg_safety_event_t g_retry_queue[VG_RETRY_QUEUE_SIZE];
static int g_retry_head = 0;
static int g_retry_count = 0;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Parse URL into host and port.
 */

static void parse_url(const char *url)
{
  const char *p;

  if (!url)
    {
      return;
    }

  /* Skip protocol */

  p = strstr(url, "://");
  if (p)
    {
      p += 3;
    }
  else
    {
      p = url;
    }

  /* Extract host:port */

  const char *colon = strchr(p, ':');
  const char *slash = strchr(p, '/');

  if (colon)
    {
      size_t host_len = colon - p;
      if (host_len >= sizeof(g_console_host))
        {
          host_len = sizeof(g_console_host) - 1;
        }

      memcpy(g_console_host, p, host_len);
      g_console_host[host_len] = '\0';
      g_console_port = atoi(colon + 1);
    }
  else
    {
      size_t host_len = slash ? (size_t)(slash - p) : strlen(p);
      if (host_len >= sizeof(g_console_host))
        {
          host_len = sizeof(g_console_host) - 1;
        }

      memcpy(g_console_host, p, host_len);
      g_console_host[host_len] = '\0';
      g_console_port = 80;
    }
}

/**
 * @brief Send HTTP POST request to console.
 * @return 0 on success, negative errno on failure.
 */

static int http_post_event(const vg_safety_event_t *event)
{
  int sockfd;
  struct sockaddr_in server_addr;
  struct hostent *server;
  char json[1024];
  char request[2048];
  int json_len;
  int req_len;
  int ret;

  /* Serialize event to JSON */

  json_len = vg_event_to_json(event, json, sizeof(json));
  if (json_len <= 0)
    {
      return -EINVAL;
    }

  /* Resolve hostname */

  server = gethostbyname(g_console_host);
  if (!server)
    {
      g_console_reachable = false;
      return -EHOSTUNREACH;
    }

  /* Create socket */

  sockfd = socket(AF_INET, SOCK_STREAM, 0);
  if (sockfd < 0)
    {
      return -errno;
    }

  /* Set timeout */

  struct timeval tv;
  tv.tv_sec = 3;
  tv.tv_usec = 0;
  setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
  setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

  /* Connect */

  memset(&server_addr, 0, sizeof(server_addr));
  server_addr.sin_family = AF_INET;
  memcpy(&server_addr.sin_addr.s_addr, server->h_addr,
         server->h_length);
  server_addr.sin_port = htons(g_console_port);

  ret = connect(sockfd, (struct sockaddr *)&server_addr,
                sizeof(server_addr));
  if (ret < 0)
    {
      close(sockfd);
      g_console_reachable = false;
      return -errno;
    }

  /* Build HTTP request */

  req_len = snprintf(request, sizeof(request),
    "POST /events HTTP/1.1\r\n"
    "Host: %s:%d\r\n"
    "Content-Type: application/json\r\n"
    "Content-Length: %d\r\n"
    "Connection: close\r\n"
    "\r\n"
    "%s",
    g_console_host, g_console_port,
    json_len, json);

  /* Send request */

  ret = send(sockfd, request, req_len, 0);
  close(sockfd);

  if (ret < 0)
    {
      g_console_reachable = false;
      return -errno;
    }

  g_console_reachable = true;
  return 0;
}

/**
 * @brief Add event to retry queue.
 */

static void enqueue_retry(const vg_safety_event_t *event)
{
  int idx;

  if (g_retry_count >= VG_RETRY_QUEUE_SIZE)
    {
      /* Queue full, drop oldest */

      g_retry_head = (g_retry_head + 1) % VG_RETRY_QUEUE_SIZE;
      g_retry_count--;
    }

  idx = (g_retry_head + g_retry_count) % VG_RETRY_QUEUE_SIZE;
  memcpy(&g_retry_queue[idx], event, sizeof(vg_safety_event_t));
  g_retry_count++;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_uploader_init(const char *console_url)
{
  if (console_url)
    {
      strlcpy(g_console_url, console_url, sizeof(g_console_url));
      parse_url(console_url);
    }

  g_retry_head = 0;
  g_retry_count = 0;
  g_console_reachable = false;

  printf("[UPLOAD] Uploader initialized, console: %s:%d\n",
         g_console_host, g_console_port);
  return 0;
}

int vg_uploader_send(const vg_safety_event_t *event)
{
  int ret;

  if (!event)
    {
      return -EINVAL;
    }

  /* Only upload escalated or manual test events */

  if (event->upload_reason == VG_UPLOAD_SYNC &&
      event->level < VG_LEVEL_EMERGENCY)
    {
      return 0;
    }

  ret = http_post_event(event);
  if (ret == 0)
    {
      printf("[UPLOAD] Event %s sent to console\n", event->event_id);
      return 0;
    }

  /* Failed: queue for retry */

  printf("[UPLOAD] Event %s queued for retry (offline)\n",
         event->event_id);
  enqueue_retry(event);
  return -ENETUNREACH;
}

int vg_uploader_retry(void)
{
  int sent = 0;
  int i;

  if (g_retry_count == 0)
    {
      return 0;
    }

  printf("[UPLOAD] Retrying %d queued events\n", g_retry_count);

  for (i = 0; i < g_retry_count; i++)
    {
      int idx = (g_retry_head + i) % VG_RETRY_QUEUE_SIZE;
      int ret = http_post_event(&g_retry_queue[idx]);

      if (ret == 0)
        {
          printf("[UPLOAD] Queued event %s sent successfully\n",
                 g_retry_queue[idx].event_id);
          sent++;
        }
      else
        {
          break; /* Still offline, keep remaining queued */
        }
    }

  /* Remove sent events from queue */

  if (sent > 0)
    {
      g_retry_head = (g_retry_head + sent) % VG_RETRY_QUEUE_SIZE;
      g_retry_count -= sent;
    }

  return sent;
}

int vg_uploader_get_pending_count(void)
{
  return g_retry_count;
}

void vg_uploader_set_url(const char *url)
{
  if (url)
    {
      strlcpy(g_console_url, url, sizeof(g_console_url));
      parse_url(url);
    }
}

bool vg_uploader_is_console_reachable(void)
{
  return g_console_reachable;
}

