/**
 * @file velaguard_main.c
 * @brief VelaGuard main application entry point.
 *        Initializes all modules and runs the main event loop.
 *
 * Usage: velaguard [simulate|monitor|inject <type>]
 *   simulate  - Run in simulation mode (demo)
 *   monitor   - Run with real audio monitoring
 *   inject    - Inject a simulated event
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
