#include "audio_detector/audio_detector.h"
#include "enrollment/enrollment.h"
#include "uploader/uploader.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool g_running = false;
static int g_history_scroll = 0;
static pthread_t g_tick_thread;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/**
 * @brief Event notification callback: called when event level changes.
 */

static void on_event_notify(const vg_safety_event_t *event)
{
  if (!event)
    {
      return;
    }

  /* Log the event */

  vg_event_log_append(event);

  /* Update hardware based on level */

  switch (event->level)
    {
      case VG_LEVEL_NOTICE:
        vg_hw_set_led(VG_LED_GREEN, 1);
        vg_hw_play_tone(VG_LEVEL_NOTICE);
        break;

      case VG_LEVEL_WARNING:
        vg_hw_set_led(VG_LED_YELLOW, 3);
        vg_hw_play_tone(VG_LEVEL_WARNING);
        vg_hw_wake_backlight();
        vg_hw_set_page(VG_PAGE_CONFIRM);
        break;

      case VG_LEVEL_EMERGENCY:
        vg_hw_set_led(VG_LED_RED, 3);
        vg_hw_play_tone(VG_LEVEL_EMERGENCY);
        vg_hw_wake_backlight();
        vg_hw_set_page(VG_PAGE_CONFIRM);

        /* Upload to console */

        vg_uploader_send(event);
        break;

      default:
        break;
    }

  /* Update display */

  const vg_safety_event_t *priority =
    vg_state_machine_get_priority_event();
  if (priority)
    {
      vg_hw_update_confirm_page(priority, 0);
    }
}

/**
 * @brief Time reliability callback.
 */

static bool on_time_reliable(void)
{
  return vg_hw_time_synced();
}

/**
 * @brief Periodic tick thread: runs once per second.
 */

static void *tick_thread(void *arg)
{
  while (g_running)
    {
      vg_state_machine_tick();

      /* Retry uploads periodically */

      static int retry_counter = 0;
      if (++retry_counter >= 30)
        {
          retry_counter = 0;
          vg_uploader_retry();
        }

      sleep(1);
    }

  return NULL;
}

/**
 * @brief Button event handler.
 */

static void on_button(int key)
{
  const vg_safety_event_t *event;

  switch (key)
    {
      case VG_BTN_OK:
        {
          /* Confirm current event as handled */

          event = vg_state_machine_get_priority_event();
          if (event)
            {
              vg_state_machine_confirm_handled(event->event_id);
              vg_hw_stop_tone();
              vg_hw_set_led(VG_LED_GREEN, 4);
              vg_hw_set_page(VG_PAGE_MONITOR);
              printf("[VELAGUARD] Event %s confirmed as handled\n",
                     event->event_id);
            }
          break;
        }

      case VG_BTN_BACK:
        {
          /* Mark as false alarm */

          event = vg_state_machine_get_priority_event();
          if (event)
            {
              vg_state_machine_confirm_false_alarm(event->event_id);
              vg_hw_stop_tone();
              vg_hw_set_led(VG_LED_GREEN, 4);
              vg_hw_set_page(VG_PAGE_MONITOR);
              printf("[VELAGUARD] Event %s marked as false alarm\n",
                     event->event_id);
            }
          break;
        }

      case VG_BTN_DOWN:
        {
          /* Snooze */

          event = vg_state_machine_get_priority_event();
          if (event)
            {
              int ret = vg_state_machine_snooze(event->event_id);
              if (ret == 0)
                {
                  vg_hw_stop_tone();
                  vg_hw_set_led(VG_LED_GREEN, 4);
                  vg_hw_set_page(VG_PAGE_MONITOR);
                  printf("[VELAGUARD] Event %s snoozed\n",
                         event->event_id);
                }
              else
                {
                  printf("[VELAGUARD] Event %s max snooze reached\n",
                         event->event_id);
                }
            }
          break;
        }

      case VG_BTN_UP:
        {
          /* Scroll history */

          if (vg_hw_get_page() == VG_PAGE_HISTORY)
            {
              if (g_history_scroll > 0)
                {
                  g_history_scroll--;
                }

              vg_safety_event_t history[20];
              int count = vg_state_machine_get_history(history, 20);
              vg_hw_update_history_page(history, count,
                                         g_history_scroll);
            }
          break;
        }

      case VG_BTN_MENU:
        {
          /* Toggle between pages */

          int page = vg_hw_get_page();
          if (page == VG_PAGE_MONITOR)
            {
              vg_hw_set_page(VG_PAGE_HISTORY);
              g_history_scroll = 0;
              vg_safety_event_t history[20];
              int count = vg_state_machine_get_history(history, 20);
              vg_hw_update_history_page(history, count, 0);
            }
          else
            {
              vg_hw_set_page(VG_PAGE_MONITOR);
            }
          break;
        }

      default:
        break;
    }
}

/**
 * @brief Display help message.
 */

static void show_help(void)
{
  printf("\n=== VelaGuard - 安聆 无摄像头家庭异常声景 AI Agent ===\n");
  printf("\n");
  printf("Commands:\n");
  printf("  help          - Show this help\n");
  printf("  status        - Show system status\n");
  printf("  history       - Show event history\n");
  printf("  enroll        - Start enrollment mode\n");
  printf("  inject <type> - Inject simulated event\n");
  printf("    Types: alarm, distress, water, name, impact\n");
  printf("  confirm       - Confirm current event as handled\n");
  printf("  false_alarm   - Mark current event as false alarm\n");
  printf("  snooze        - Snooze current event\n");
  printf("  page <n>      - Switch LCD page (0=monitor,1=confirm,2=history)\n");
  printf("  quit          - Exit VelaGuard\n");
  printf("\n");
}

/**
 * @brief Process serial command input.
 */

static void process_command(const char *cmd)
{
  if (strcmp(cmd, "help") == 0 || strcmp(cmd, "h") == 0)
    {
      show_help();
    }
  else if (strcmp(cmd, "status") == 0)
    {
      printf("\n[VelaGuard Status]\n");
      printf("Guard: %s\n",
             vg_audio_is_active() ? "ACTIVE" : "PAUSED");
      printf("Active events: %d\n",
             vg_state_machine_get_active_count());
      printf("History events: %d\n", vg_event_log_get_count());
      printf("Enrollments: %d\n", vg_enrollment_get_count());
      printf("Upload pending: %d\n", vg_uploader_get_pending_count());
      printf("Console: %s\n",
             vg_uploader_is_console_reachable() ?
               "reachable" : "unreachable");
    }
  else if (strcmp(cmd, "history") == 0)
    {
      vg_safety_event_t history[20];
      int count = vg_state_machine_get_history(history, 20);
      vg_hw_update_history_page(history, count, 0);
    }
  else if (strncmp(cmd, "inject ", 7) == 0)
    {
      const char *type = cmd + 7;
      vg_sound_observation_t obs;
      vg_distress_observation_t dist;

      memset(&obs, 0, sizeof(obs));
      memset(&dist, 0, sizeof(dist));

      if (strcmp(type, "alarm") == 0)
        {
          obs.type = VG_EVENT_ALARM_BEEP;
          obs.confidence = 0.95f;
          obs.window_ms = 1000;
          vg_audio_simulate_sound(&obs);
        }
      else if (strcmp(type, "distress") == 0)
        {
          dist.type = VG_EVENT_DISTRESS_VOICE;
          dist.confidence = 0.85f;
          dist.urgency = 2;
          dist.repeat_count = 3;
          strlcpy(dist.matched_phrase, "救命",
                  VG_MATCHED_PHRASE_LEN);
          vg_audio_simulate_distress(&dist);
        }
      else if (strcmp(type, "water") == 0)
        {
          obs.type = VG_EVENT_WATER_FLOW;
          obs.confidence = 0.80f;
          obs.window_ms = 1000;
          vg_audio_simulate_sound(&obs);
        }
      else if (strcmp(type, "name") == 0)
        {
          dist.type = VG_EVENT_NAME_CALL_HELP;
          dist.confidence = 0.86f;
          dist.urgency = 2;
          dist.repeat_count = 3;
          strlcpy(dist.matched_phrase, "快来人",
                  VG_MATCHED_PHRASE_LEN);
          strlcpy(dist.person_label, "家庭成员A",
                  VG_PERSON_LABEL_LEN);
          vg_audio_simulate_distress(&dist);
        }
      else if (strcmp(type, "impact") == 0)
        {
          obs.type = VG_EVENT_IMPACT;
          obs.confidence = 0.90f;
          obs.window_ms = 500;
          vg_audio_simulate_sound(&obs);
        }
      else
        {
          printf("Unknown type: %s\n", type);
          printf("Valid: alarm, distress, water, name, impact\n");
        }
    }
  else if (strcmp(cmd, "confirm") == 0 || strcmp(cmd, "ok") == 0)
    {
      on_button(VG_BTN_OK);
    }
  else if (strcmp(cmd, "false_alarm") == 0 || strcmp(cmd, "fa") == 0)
    {
      on_button(VG_BTN_BACK);
    }
  else if (strcmp(cmd, "snooze") == 0 || strcmp(cmd, "sz") == 0)
    {
      on_button(VG_BTN_DOWN);
    }
  else if (strncmp(cmd, "page ", 5) == 0)
    {
      int page = atoi(cmd + 5);
      vg_hw_set_page(page);
    }
  else if (strcmp(cmd, "quit") == 0 || strcmp(cmd, "q") == 0)
    {
      g_running = false;
    }
  else
    {
      printf("Unknown command: %s (type 'help' for commands)\n", cmd);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  char line[256];

  printf("\n");
  printf("╔══════════════════════════════════════════════════════════╗\n");
  printf("║     安聆 VelaGuard - 无摄像头家庭异常声景 AI Agent      ║\n");
  printf("║                                                         ║\n");
  printf("║  识别五类安全声景:                                      ║\n");
  printf("║  1. 烟雾/燃气报警蜂鸣 (alarm_beep)                     ║\n");
  printf("║  2. 呻吟/痛苦叫声/哭喊 (distress_voice)                ║\n");
  printf("║  3. 持续水流/疑似漏水 (water_flow)                     ║\n");
  printf("║  4. 姓名/称呼/方言求救 (name_call_help)                ║\n");
  printf("║  5. 玻璃破碎/重物撞击 (impact)                         ║\n");
  printf("╚══════════════════════════════════════════════════════════╝\n");
  printf("\n");

  /* Initialize all modules */

  printf("[VELAGUARD] Initializing modules...\n");

  /* 1. Event log (persistent storage) */

  if (vg_event_log_init() < 0)
    {
      printf("[VELAGUARD] WARNING: Event log init failed\n");
    }

  /* 2. Enrollment */

  if (vg_enrollment_init() < 0)
    {
      printf("[VELAGUARD] WARNING: Enrollment init failed\n");
    }

  /* 3. Hardware adapter */

  if (vg_hw_init() < 0)
    {
      printf("[VELAGUARD] ERROR: Hardware init failed\n");
      return 1;
    }

  /* 4. State machine */

  if (vg_state_machine_init(on_event_notify, on_time_reliable) < 0)
    {
      printf("[VELAGUARD] ERROR: State machine init failed\n");
      return 1;
    }

  /* 5. Audio detector */

  if (vg_audio_init(vg_state_machine_feed_sound,
                    vg_state_machine_feed_distress) < 0)
    {
      printf("[VELAGUARD] ERROR: Audio detector init failed\n");
      return 1;
    }

  /* 6. Uploader */

  vg_uploader_init(NULL); /* Uses default URL or config.json */

  /* Register button handler */

  vg_hw_register_button_cb(on_button);

  /* Start tick thread */

  g_running = true;
  pthread_create(&g_tick_thread, NULL, tick_thread, NULL);

  /* Start audio monitoring if requested */

  if (argc > 1 && strcmp(argv[1], "monitor") == 0)
    {
      vg_audio_start();
      printf("[VELAGUARD] Audio monitoring started\n");
    }
  else
    {
      printf("[VELAGUARD] Running in simulation mode\n");
      printf("[VELAGUARD] Use 'inject <type>' to simulate events\n");
    }

  /* Update monitor page */

  vg_hw_update_monitor_page(vg_audio_is_active(),
                             vg_hw_wifi_connected(),
                             vg_hw_time_synced(), NULL);

  /* Show help */

  show_help();

  /* Main command loop */

  printf("velaguard> ");
  fflush(stdout);

  while (g_running)
    {
      if (fgets(line, sizeof(line), stdin) == NULL)
        {
          break;
        }

      /* Remove trailing newline */

      char *nl = strchr(line, '\n');
      if (nl)
        {
          *nl = '\0';
        }

      /* Skip empty lines */

      if (strlen(line) == 0)
        {
          printf("velaguard> ");
          fflush(stdout);
          continue;
        }

      process_command(line);

      printf("velaguard> ");
      fflush(stdout);
    }

  /* Cleanup */

  printf("[VELAGUARD] Shutting down...\n");

  vg_audio_stop();
  g_running = false;
  pthread_join(g_tick_thread, NULL);

  vg_enrollment_save();

  printf("[VELAGUARD] VelaGuard stopped.\n");
  return 0;
}

{
  "name": "velaguard-console",
  "version": "1.0.0",
  "description": "VelaGuard Prototype Console - LAN notification and demo interface",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js --dev"
  },
  "dependencies": {
    "express": "^4.18.2",
    "better-sqlite3": "^9.0.0",
    "cors": "^2.8.5"
  },
  "license": "Apache-2.0"
}

/**
 * VelaGuard Prototype Console
 *
 * LAN-based notification and demo interface for VelaGuard.
 * Supports: POST /events, GET /events, PATCH /events/:id, GET /stream (SSE)
 *
 * Reference: PRD-05 通知与演示控制台
 */

const express = require('express');
const cors = require('cors');
const path = require('path');
const Database = require('better-sqlite3');

const app = express();
const PORT = process.env.PORT || 3000;

// Database setup

const db = new Database(path.join(__dirname, 'velaguard.db'));

db.exec(`
  CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id TEXT UNIQUE NOT NULL,
    device_id TEXT,
    event_type TEXT NOT NULL,
    level TEXT NOT NULL,
    confidence REAL,
    started_at TEXT,
    duration_sec INTEGER DEFAULT 0,
    local_status TEXT DEFAULT 'pending',
    upload_reason TEXT,
    time_reliable INTEGER DEFAULT 1,
    matched_phrase TEXT,
    person_label TEXT,
    urgency INTEGER DEFAULT 0,
    repeat_count INTEGER DEFAULT 0,
    summary TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

// Middleware

app.use(cors());
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// SSE clients

const sseClients = new Set();

/**
 * Broadcast event to all connected SSE clients
 */
function broadcastEvent(event) {
  const data = JSON.stringify(event);
  for (const client of sseClients) {
    client.write(`data: ${data}\n\n`);
  }
}

// Routes

/**
 * POST /events - Upload a safety event
 */
app.post('/events', (req, res) => {
  const event = req.body;

  if (!event.eventId || !event.eventType || !event.level) {
    return res.status(400).json({
      error: 'Missing required fields: eventId, eventType, level'
    });
  }

  const stmt = db.prepare(`
    INSERT OR REPLACE INTO events
    (event_id, device_id, event_type, level, confidence, started_at,
     duration_sec, local_status, upload_reason, time_reliable,
     matched_phrase, person_label, urgency, repeat_count, summary)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  stmt.run(
    event.eventId,
    event.deviceId || 'velaguard_demo_001',
    event.eventType,
    event.level,
    event.confidence || 0,
    event.startedAt || new Date().toISOString(),
    event.durationSec || 0,
    event.localStatus || 'pending',
    event.uploadReason || 'sync',
    event.timeReliable !== false ? 1 : 0,
    event.matchedPhrase || null,
    event.personLabel || null,
    event.urgency || 0,
    event.repeatCount || 0,
    event.summary || null
  );

  // Broadcast to SSE clients
  broadcastEvent(event);

  console.log(`[EVENT] ${event.eventType} (${event.level}) from ${event.deviceId || 'unknown'}`);

  res.status(201).json({ success: true, eventId: event.eventId });
});

/**
 * GET /events - List events
 */
app.get('/events', (req, res) => {
  const limit = parseInt(req.query.limit) || 100;
  const offset = parseInt(req.query.offset) || 0;
  const level = req.query.level;
  const type = req.query.type;

  let query = 'SELECT * FROM events';
  const params = [];

  if (level || type) {
    const conditions = [];
    if (level) {
      conditions.push('level = ?');
      params.push(level);
    }
    if (type) {
      conditions.push('event_type = ?');
      params.push(type);
    }
    query += ' WHERE ' + conditions.join(' AND ');
  }

  query += ' ORDER BY created_at DESC LIMIT ? OFFSET ?';
  params.push(limit, offset);

  const events = db.prepare(query).all(...params);
  res.json(events);
});

/**
 * GET /events/:id - Get event detail
 */
app.get('/events/:id', (req, res) => {
  const event = db.prepare('SELECT * FROM events WHERE event_id = ?')
    .get(req.params.id);

  if (!event) {
    return res.status(404).json({ error: 'Event not found' });
  }

  res.json(event);
});

/**
 * PATCH /events/:id - Update event status
 */
app.patch('/events/:id', (req, res) => {
  const { localStatus } = req.body;
  const validStatuses = ['pending', 'handled', 'false_alarm', 'snoozed', 'no_response'];

  if (!validStatuses.includes(localStatus)) {
    return res.status(400).json({
      error: `Invalid status. Valid: ${validStatuses.join(', ')}`
    });
  }

  const stmt = db.prepare(`
    UPDATE events SET local_status = ?, updated_at = CURRENT_TIMESTAMP
    WHERE event_id = ?
  `);

  const result = stmt.run(localStatus, req.params.id);

  if (result.changes === 0) {
    return res.status(404).json({ error: 'Event not found' });
  }

  const event = db.prepare('SELECT * FROM events WHERE event_id = ?')
    .get(req.params.id);

  // Broadcast update
  broadcastEvent({ ...event, _update: true });

  res.json(event);
});

/**
 * GET /stream - SSE event stream
 */
app.get('/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive'
  });

  // Send initial connection event
  res.write(`data: ${JSON.stringify({ type: 'connected', timestamp: new Date().toISOString() })}\n\n`);

  sseClients.add(res);
  console.log(`[SSE] Client connected (total: ${sseClients.size})`);

  req.on('close', () => {
    sseClients.delete(res);
    console.log(`[SSE] Client disconnected (total: ${sseClients.size})`);
  });
});

/**
 * GET /stats - Get event statistics
 */
app.get('/stats', (req, res) => {
  const stats = {
    total: db.prepare('SELECT COUNT(*) as count FROM events').get().count,
    byLevel: {
      notice: db.prepare("SELECT COUNT(*) as count FROM events WHERE level = 'notice'").get().count,
      warning: db.prepare("SELECT COUNT(*) as count FROM events WHERE level = 'warning'").get().count,
      emergency: db.prepare("SELECT COUNT(*) as count FROM events WHERE level = 'emergency'").get().count
    },
    byType: {
      alarm_beep: db.prepare("SELECT COUNT(*) as count FROM events WHERE event_type = 'alarm_beep'").get().count,
      distress_voice: db.prepare("SELECT COUNT(*) as count FROM events WHERE event_type = 'distress_voice'").get().count,
      water_flow: db.prepare("SELECT COUNT(*) as count FROM events WHERE event_type = 'water_flow'").get().count,
      name_call_help: db.prepare("SELECT COUNT(*) as count FROM events WHERE event_type = 'name_call_help'").get().count,
      impact: db.prepare("SELECT COUNT(*) as count FROM events WHERE event_type = 'impact'").get().count
    },
    sseClients: sseClients.size
  };

  res.json(stats);
});

// Start server

app.listen(PORT, '0.0.0.0', () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║        VelaGuard Console - LAN Notification Server       ║
║                                                          ║
║  Server: http://0.0.0.0:${PORT}                            ║
║  SSE:    http://0.0.0.0:${PORT}/stream                     ║
║                                                          ║
║  Open this URL on family member's phone browser:         ║
║  http://<this-ip>:${PORT}                                  ║
╚══════════════════════════════════════════════════════════╝
  `);
});

// Graceful shutdown

process.on('SIGINT', () => {
  console.log('\n[CONSOLE] Shutting down...');
  db.close();
  process.exit(0);
});

process.on('SIGTERM', () => {
  db.close();
  process.exit(0);
});

