265	        break;
266	      case VG_EVENT_ALARM_BEEP:
267	        p += 30;
268	        break;
269	      case VG_EVENT_IMPACT:
270	        p += 20;
271	        break;
272	      case VG_EVENT_WATER_FLOW:
273	        p += 10;
274	        break;
275	      default:
276	        break;
277	    }
