300	void vg_state_machine_feed_sound(const vg_sound_observation_t *obs)
301	{
302	  int idx;
303	  uint32_t now = get_monotonic_sec();
304	
305	  if (!obs)
306	    {
307	      return;
308	    }
309	
310	  /* Try to find existing active event of this type */
311	
312	  idx = find_active_by_type(obs->type);
313	  if (idx < 0)
314	    {
315	      /* Create new event */
316	
317	      idx = alloc_active_slot();
318	      if (idx < 0)
319	        {
320	          return;  /* Slots full */
321	        }
322	
323	      generate_event_id(g_active_events[idx].event.event_id,
324	                        VG_EVENT_ID_LEN);
325	      strlcpy(g_active_events[idx].event.device_id,
326	              VG_DEFAULT_DEVICE_ID, VG_DEVICE_ID_LEN);
327	      g_active_events[idx].event.event_type = obs->type;
328	      g_active_events[idx].event.level = VG_LEVEL_NOTICE;
329	      g_active_events[idx].event.confidence = obs->confidence;
330	      g_active_events[idx].event.local_status = VG_STATUS_PENDING;
331	      g_active_events[idx].event.upload_reason = VG_UPLOAD_ESCALATED;
332	      g_active_events[idx].event.time_reliable = true;
333	      if (g_time_cb)
334	        {
335	          g_active_events[idx].event.time_reliable = g_time_cb();
336	        }
337	
338	      format_timestamp(g_active_events[idx].event.started_at,
339	                       VG_TIMESTAMP_LEN);
340	      g_active_events[idx].first_seen_sec = now;
341	      g_active_events[idx].last_seen_sec = now;
342	      g_active_events[idx].continuous_sec = 1;
343	      g_active_events[idx].repeat_count = 1;
344	    }
345	  else
346	    {
347	      /* Update existing event */
348	
349	      g_active_events[idx].last_seen_sec = now;
350	      g_active_events[idx].continuous_sec =
351	        now - g_active_events[idx].first_seen_sec;
352	
353	      /* Check if detection is still continuous (within 2s gap) */
354	
355	      if (now - g_active_events[idx].last_seen_sec > 2)
356	        {
357	          g_active_events[idx].continuous_sec = 1;
358	          g_active_events[idx].first_seen_sec = now;
359	        }
360	
361	      g_active_events[idx].repeat_count++;
362	      if (obs->confidence > g_active_events[idx].event.confidence)
363	        {
364	          g_active_events[idx].event.confidence = obs->confidence;
365	        }
366	    }
367	
368	  /* Apply event-specific rules */
369	
370	  switch (obs->type)
371	    {
372	      case VG_EVENT_ALARM_BEEP:
373	        {
374	          /* High confidence continuous ~5s -> emergency directly */
375	
376	          if (g_active_events[idx].event.confidence >= 0.7f &&
377	              g_active_events[idx].continuous_sec >= g_alarm_emergency_sec)
378	            {
379	              set_event_level(idx, VG_LEVEL_EMERGENCY);
380	            }
381	          break;
382	        }
383	
384	      case VG_EVENT_WATER_FLOW:
385	        {
386	          uint32_t dur = g_active_events[idx].continuous_sec;
387	
388	          if (dur >= g_water_warning_sec +
389	              g_water_emergency_after_warning_sec &&
390	              g_active_events[idx].event.level == VG_LEVEL_WARNING)
391	            {
392	              /* Warning exceeded, upgrade to emergency */
393	
394	              set_event_level(idx, VG_LEVEL_EMERGENCY);
395	              g_active_events[idx].event.local_status =
396	                VG_STATUS_NO_RESPONSE;
397	            }
398	          else if (dur >= g_water_warning_sec)
399	            {
400	              set_event_level(idx, VG_LEVEL_WARNING);
401	              if (!g_active_events[idx].countdown_started)
402	                {
403	                  g_active_events[idx].countdown_started = true;
404	                  g_active_events[idx].countdown_start_sec = now;
405	                }
406	            }
407	          else if (dur >= g_water_notice_sec)
408	            {
409	              set_event_level(idx, VG_LEVEL_NOTICE);
410	            }
411	          break;
412	        }
413	
414	      case VG_EVENT_IMPACT:
415	        {
416	          /* Single high-confidence -> warning */
417	
418	          if (g_active_events[idx].event.confidence >= 0.7f &&
419	              g_active_events[idx].repeat_count == 1)
420	            {
421	              set_event_level(idx, VG_LEVEL_WARNING);
422	              if (!g_active_events[idx].countdown_started)
423	                {
424	                  g_active_events[idx].countdown_started = true;
425	                  g_active_events[idx].countdown_start_sec = now;
426	                }
427	            }
428	
429	          /* Night or repeated within window -> emergency */
430	
431	          if (vg_state_machine_is_night() ||
432	              (g_active_events[idx].repeat_count >= g_impact_repeat_count &&
433	               g_active_events[idx].continuous_sec <=
434	               g_impact_repeat_window_sec))
435	            {
436	              set_event_level(idx, VG_LEVEL_EMERGENCY);
437	            }
438	          break;
439	        }
440	
441	      default:
442	        break;
443	    }
444	}
