594	int vg_state_machine_snooze(const char *event_id)
595	{
596	  int idx = find_active_event(event_id);
597	  if (idx < 0)
598	    {
599	      return -ENOENT;
600	    }
601	
602	  if (g_active_events[idx].snooze_count >= VG_MAX_SNOOZE_COUNT)
603	    {
604	      /* Third snooze: treat as no_response and escalate */
605	
606	      g_active_events[idx].event.local_status = VG_STATUS_NO_RESPONSE;
607	      set_event_level(idx, VG_LEVEL_EMERGENCY);
608	      return -EAGAIN;
609	    }
610	
611	  g_active_events[idx].snooze_count++;
612	  g_active_events[idx].event.local_status = VG_STATUS_SNOOZED;
613	  g_active_events[idx].countdown_started = false;
614	
615	  /* Record in history */
616	
617	  add_to_history(&g_active_events[idx].event);
618	  return 0;
619	}
