621	void vg_state_machine_tick(void)
622	{
623	  uint32_t now = get_monotonic_sec();
624	  int i;
625	
626	  for (i = 0; i < VG_MAX_ACTIVE_EVENTS; i++)
627	    {
628	      if (!g_active_events[i].is_active)
629	        {
630	          continue;
631	        }
632	
633	      /* Handle snooze timeout */
634	
635	      if (g_active_events[i].event.local_status == VG_STATUS_SNOOZED)
636	        {
637	          /* Check if snooze period elapsed */
638	
639	          if (now - g_active_events[i].last_seen_sec >=
640	              VG_SNOOZE_DURATION_SEC)
641	            {
642	              /* Re-enter warning countdown */
643	
644	              g_active_events[i].event.local_status = VG_STATUS_PENDING;
645	              g_active_events[i].countdown_started = true;
646	              g_active_events[i].countdown_start_sec = now;
647	              g_active_events[i].last_seen_sec = now;
648	              set_event_level(i, VG_LEVEL_WARNING);
649	            }
650	          continue;
651	        }
652	
653	      /* Handle warning countdown expiry */
654	
655	      if (g_active_events[i].countdown_started &&
656	          g_active_events[i].event.level == VG_LEVEL_WARNING)
657	        {
658	          if (now - g_active_events[i].countdown_start_sec >=
659	              VG_WARNING_TIMEOUT_SEC)
660	            {
661	              /* Timeout: no response -> emergency */
662	
663	              g_active_events[i].event.local_status =
664	                VG_STATUS_NO_RESPONSE;
665	              set_event_level(i, VG_LEVEL_EMERGENCY);
666	            }
667	        }
668	
669	      /* Age out very old events that haven't been detected recently */
670	
671	      if (now - g_active_events[i].last_seen_sec > 300)
672	        {
673	          close_event(i, VG_STATUS_NO_RESPONSE);
674	        }
675	    }
676	}
