202	static void extract_features(const int16_t *audio, uint32_t samples,
203	                             float *features, int dim)
204	{
205	  uint32_t i;
206	  int d;
207	  float sum;
208	  float mean;
209	
210	  /* Simple energy-based features per sub-band */
211	
212	  int band_size = samples / dim;
213	  if (band_size < 1)
214	    {
215	      band_size = 1;
216	    }
217	
218	  /* Calculate mean for DC removal */
219	
220	  sum = 0.0f;
221	  for (i = 0; i < samples; i++)
222	    {
223	      sum += (float)audio[i];
224	    }
225	
226	  mean = sum / samples;
227	
228	  for (d = 0; d < dim; d++)
229	    {
230	      uint32_t start = d * band_size;
231	      uint32_t end = start + band_size;
232	      float energy = 0.0f;
233	
234	      if (end > samples)
235	        {
236	          end = samples;
237	        }
238	
239	      for (i = start; i < end; i++)
240	        {
241	          float sample = (float)audio[i] - mean;
242	          energy += sample * sample;
243	        }
244	
245	      features[d] = sqrtf(energy / band_size) / 32768.0f;
246	    }
247	}
