249	/**
250	 * @brief Calculate cosine similarity between two feature vectors.
251	 */
252	
253	static float cosine_similarity(const float *a, const float *b, int dim)
254	{
255	  float dot = 0.0f;
256	  float norm_a = 0.0f;
257	  float norm_b = 0.0f;
258	  int i;
259	
260	  for (i = 0; i < dim; i++)
261	    {
262	      dot += a[i] * b[i];
263	      norm_a += a[i] * a[i];
264	      norm_b += b[i] * b[i];
265	    }
266	
267	  if (norm_a < 1e-10f || norm_b < 1e-10f)
268	    {
269	      return 0.0f;
270	    }
271	
272	  return dot / (sqrtf(norm_a) * sqrtf(norm_b));
273	}
